CREATE OR REPLACE FUNCTION nexus.manifest_names_key( p_where jsonb, p_path text, p_key text ) RETURNS boolean LANGUAGE sql IMMUTABLE PARALLEL SAFE SECURITY INVOKER AS $$ SELECT COALESCE(jsonb_exists(p_where, p_key), false) OR COALESCE(position('"' || p_key || '"' IN p_path), 0) > 0 $$;
CREATE OR REPLACE FUNCTION nexus.manifest_search_384( p_query nexus.vector(384), p_query_text text, p_chashes bytea[], p_collections text[], p_where jsonb, p_where_path text, p_manifest_where jsonb, p_manifest_path text, p_n int, p_embedding_model text, p_tenant text ) RETURNS TABLE(id text, content text, collection text, distance float8, metadata jsonb, retention text) LANGUAGE sql STABLE SECURITY INVOKER AS $$ SELECT encode(c.chash, 'hex'), c.chunk_text, c.collection, (c.embedding_384 OPERATOR(nexus.<=>) p_query)::float8, c.metadata, c.retention FROM nexus.chunks c WHERE c.embedding_model = p_embedding_model AND c.tenant_id = p_tenant AND c.collection = ANY(p_collections) AND c.embedding_384 IS NOT NULL AND (p_chashes IS NULL OR c.chash = ANY(p_chashes)) AND EXISTS (SELECT 1 FROM nexus.chunk_live_owners(c.tenant_id, c.collection, c.chash)) AND (p_where IS NULL OR c.metadata @> p_where) AND (p_where_path IS NULL OR c.metadata @@ p_where_path::jsonpath) AND (p_query_text IS NULL OR c.chunk_tsv @@ plainto_tsquery('english', p_query_text) OR p_query_text OPERATOR(nexus.<%) c.chunk_text) AND EXISTS ( SELECT 1 FROM nexus.catalog_document_chunks m JOIN nexus.catalog_documents d ON d.tenant_id = m.tenant_id AND d.tumbler = m.doc_id CROSS JOIN LATERAL ( SELECT nexus.catalog_source_format(d.content_type, d.file_path) AS fmt ) f CROSS JOIN LATERAL ( SELECT jsonb_build_object( 'section_title', CASE WHEN nexus.manifest_names_key(p_manifest_where, p_manifest_path, 'section_title') THEN CASE WHEN m.labels_written THEN to_jsonb(COALESCE(m.section_title, '')) ELSE COALESCE(NULLIF(c.metadata -> 'section_title', 'null'::jsonb), '""'::jsonb) END END, 'section_type', CASE WHEN nexus.manifest_names_key(p_manifest_where, p_manifest_path, 'section_type') THEN CASE WHEN m.labels_written THEN to_jsonb(COALESCE(m.section_type, '')) ELSE COALESCE(NULLIF(c.metadata -> 'section_type', 'null'::jsonb), '""'::jsonb) END END, 'page_number', CASE WHEN nexus.manifest_names_key(p_manifest_where, p_manifest_path, 'page_number') THEN CASE WHEN m.labels_written THEN COALESCE(to_jsonb(m.page_number), '""'::jsonb) ELSE COALESCE(NULLIF(c.metadata -> 'page_number', 'null'::jsonb), '""'::jsonb) END END, 'title', CASE WHEN nexus.manifest_names_key(p_manifest_where, p_manifest_path, 'title') THEN CASE WHEN d.title ~ '\S' THEN to_jsonb(d.title) ELSE COALESCE(NULLIF(c.metadata -> 'title', 'null'::jsonb), '""'::jsonb) END END, 'source_author', CASE WHEN nexus.manifest_names_key(p_manifest_where, p_manifest_path, 'source_author') THEN CASE WHEN COALESCE(d.author, '') ~ '\S' THEN to_jsonb(d.author) ELSE COALESCE(NULLIF(c.metadata -> 'source_author', 'null'::jsonb), '""'::jsonb) END END, 'bib_doi', CASE WHEN nexus.manifest_names_key(p_manifest_where, p_manifest_path, 'bib_doi') THEN to_jsonb(d.bib_doi) END, 'bib_openalex_id', CASE WHEN nexus.manifest_names_key(p_manifest_where, p_manifest_path, 'bib_openalex_id') THEN to_jsonb(d.bib_openalex_id) END, 'bib_semantic_scholar_id', CASE WHEN nexus.manifest_names_key(p_manifest_where, p_manifest_path, 'bib_semantic_scholar_id') THEN to_jsonb(d.bib_semantic_scholar_id) END, 'content_type', CASE WHEN nexus.manifest_names_key(p_manifest_where, p_manifest_path, 'content_type') THEN to_jsonb(array_remove(ARRAY[ CASE WHEN d.content_type ~ '\S' THEN d.content_type END, f.fmt, CASE WHEN f.fmt IS NULL OR NOT (COALESCE(d.content_type, '') ~ '\S') THEN COALESCE(c.metadata ->> 'content_type', '') END ], NULL)) END, 'tags', CASE WHEN nexus.manifest_names_key(p_manifest_where, p_manifest_path, 'tags') THEN CASE WHEN p_manifest_path IS NOT NULL AND position('"tags"' in p_manifest_path) > 0 THEN nexus.catalog_tag_set(CASE WHEN COALESCE(jsonb_typeof(d.metadata -> 'tags'), 'null') <> 'null' THEN d.metadata -> 'tags' ELSE c.metadata -> 'tags' END) ELSE '[""]'::jsonb END END, 'category', CASE WHEN nexus.manifest_names_key(p_manifest_where, p_manifest_path, 'category') THEN CASE WHEN COALESCE(jsonb_typeof(d.metadata -> 'category'), 'null') <> 'null' THEN d.metadata -> 'category' ELSE COALESCE(NULLIF(c.metadata -> 'category', 'null'::jsonb), '""'::jsonb) END END, 'ttl_days', CASE WHEN nexus.manifest_names_key(p_manifest_where, p_manifest_path, 'ttl_days') THEN CASE WHEN COALESCE(jsonb_typeof(d.metadata -> 'ttl_days'), 'null') <> 'null' THEN d.metadata -> 'ttl_days' ELSE COALESCE(NULLIF(c.metadata -> 'ttl_days', 'null'::jsonb), '""'::jsonb) END END, 'source_agent', CASE WHEN nexus.manifest_names_key(p_manifest_where, p_manifest_path, 'source_agent') THEN CASE WHEN COALESCE(jsonb_typeof(d.metadata -> 'source_agent'), 'null') <> 'null' THEN d.metadata -> 'source_agent' ELSE COALESCE(NULLIF(c.metadata -> 'source_agent', 'null'::jsonb), '""'::jsonb) END END, 'extraction_method', CASE WHEN nexus.manifest_names_key(p_manifest_where, p_manifest_path, 'extraction_method') THEN CASE WHEN COALESCE(jsonb_typeof(d.metadata -> 'extraction_method'), 'null') <> 'null' THEN d.metadata -> 'extraction_method' ELSE COALESCE(NULLIF(c.metadata -> 'extraction_method', 'null'::jsonb), '""'::jsonb) END END, 'quality_gate_overridden', CASE WHEN nexus.manifest_names_key(p_manifest_where, p_manifest_path, 'quality_gate_overridden') THEN CASE WHEN COALESCE(jsonb_typeof(d.metadata -> 'quality_gate_overridden'), 'null') <> 'null' THEN d.metadata -> 'quality_gate_overridden' ELSE COALESCE(NULLIF(c.metadata -> 'quality_gate_overridden', 'null'::jsonb), '""'::jsonb) END END, 'extraction_source', CASE WHEN nexus.manifest_names_key(p_manifest_where, p_manifest_path, 'extraction_source') THEN CASE WHEN COALESCE(jsonb_typeof(d.metadata -> 'extraction_source'), 'null') <> 'null' THEN d.metadata -> 'extraction_source' ELSE COALESCE(NULLIF(c.metadata -> 'extraction_source', 'null'::jsonb), '""'::jsonb) END END, 'frecency_score', CASE WHEN nexus.manifest_names_key(p_manifest_where, p_manifest_path, 'frecency_score') THEN CASE WHEN COALESCE(jsonb_typeof(d.metadata -> 'frecency_score'), 'null') <> 'null' THEN d.metadata -> 'frecency_score' ELSE COALESCE(NULLIF(c.metadata -> 'frecency_score', 'null'::jsonb), '""'::jsonb) END END ) AS eff ) e WHERE m.tenant_id = c.tenant_id AND m.collection = c.collection AND m.chash = c.chash AND d.deleted_at IS NULL AND (p_manifest_where IS NULL OR e.eff @> p_manifest_where) AND (p_manifest_path IS NULL OR e.eff @@ p_manifest_path::jsonpath) ) ORDER BY c.embedding_384 OPERATOR(nexus.<=>) p_query, encode(c.chash, 'hex') LIMIT p_n $$;
