GRANT EXECUTE ON FUNCTION nexus.manifest_names_key(jsonb, text, text) TO nexus_svc;
DO $post$ DECLARE n int; BEGIN SELECT count(*) INTO n FROM pg_catalog.pg_proc p WHERE p.pronamespace = 'nexus'::pg_catalog.regnamespace AND p.proname = 'manifest_names_key'; IF n <> 1 THEN RAISE EXCEPTION 'vectors-045-1: expected exactly 1 manifest_names_key function, found %', n; END IF; SELECT count(*) INTO n FROM pg_catalog.pg_proc p WHERE p.pronamespace = 'nexus'::pg_catalog.regnamespace AND p.proname IN ('manifest_search_384', 'manifest_search_768', 'manifest_search_1024') AND p.prosrc LIKE '%nexus.manifest_names_key(%'; IF n <> 3 THEN RAISE EXCEPTION 'vectors-045-1: expected the 3 manifest_search functions to name keys through manifest_names_key, found %', n; END IF; END $post$;

